/** `Any` contains an arbitrary serialized protocol buffer message along with a URL that describes the type of the serialized message. In its binary encoding, an `Any` is an ordinary message; but in other… */
export interface Any {
    /** Identifies the type of the serialized Protobuf message with a URI reference consisting of a prefix ending in a slash and the fully-qualified type name. Example: type.googleapis.com/google.protobuf.Str… */
    typeUrl: string;
    /** Holds a Protobuf serialization of the type described by type_url. */
    value: Uint8Array;
}

/** `SourceContext` represents information about the source of a protobuf element, like the file in which it is defined. */
export interface SourceContext {
    /** The path-qualified name of the .proto file that contained the associated protobuf element. For example: `"google/protobuf/source_context.proto"`. */
    fileName: string;
}

/** A protocol buffer message type. New usages of this message as an alternative to DescriptorProto are strongly discouraged. This message does not reliability preserve all information necessary to model… */
export interface Type {
    /** The fully qualified message name. */
    name: string;
    /** The list of fields. */
    fields: Field[];
    /** The list of types appearing in `oneof` definitions in this type. */
    oneofs: string[];
    /** The protocol buffer options. */
    options: Option[];
    /** The source context. */
    sourceContext?: SourceContext;
    /** The source syntax. */
    syntax: Syntax;
    /** The source edition string, only valid when syntax is SYNTAX_EDITIONS. */
    edition: string;
}

/** A single field of a message type. New usages of this message as an alternative to FieldDescriptorProto are strongly discouraged. This message does not reliability preserve all information necessary to… */
export interface Field {
    /** The field type. */
    kind: Field_Kind;
    /** The field cardinality. */
    cardinality: Field_Cardinality;
    /** The field number. */
    number: number;
    /** The field name. */
    name: string;
    /** The field type URL, without the scheme, for message or enumeration types. Example: `"type.googleapis.com/google.protobuf.Timestamp"`. */
    typeUrl: string;
    /** The index of the field type in `Type.oneofs`, for message or enumeration types. The first type has index 1; zero means the type is not in the list. */
    oneofIndex: number;
    /** Whether to use alternative packed wire representation. */
    packed: boolean;
    /** The protocol buffer options. */
    options: Option[];
    /** The field JSON name. */
    jsonName: string;
    /** The string value of the default value of this field. Proto2 syntax only. */
    defaultValue: string;
}

/** Enum type definition. New usages of this message as an alternative to EnumDescriptorProto are strongly discouraged. This message does not reliability preserve all information necessary to model the sc… */
export interface Enum {
    /** Enum type name. */
    name: string;
    /** Enum value definitions. */
    enumvalue: EnumValue[];
    /** Protocol buffer options. */
    options: Option[];
    /** The source context. */
    sourceContext?: SourceContext;
    /** The source syntax. */
    syntax: Syntax;
    /** The source edition string, only valid when syntax is SYNTAX_EDITIONS. */
    edition: string;
}

/** Enum value definition. New usages of this message as an alternative to EnumValueDescriptorProto are strongly discouraged. This message does not reliability preserve all information necessary to model… */
export interface EnumValue {
    /** Enum value name. */
    name: string;
    /** Enum value number. */
    number: number;
    /** Protocol buffer options. */
    options: Option[];
}

/** A protocol buffer option, which can be attached to a message, field, enumeration, etc. New usages of this message as an alternative to FileOptions, MessageOptions, FieldOptions, EnumOptions, EnumValue… */
export interface Option {
    /** The option's name. For protobuf built-in options (options defined in descriptor.proto), this is the short name. For example, `"map_entry"`. For custom options, it should be the fully-qualified name. F… */
    name: string;
    /** The option's value packed in an Any message. If the value is a primitive, the corresponding wrapper type defined in google/protobuf/wrappers.proto should be used. If the value is an enum, it should be… */
    value?: Any;
}

/** Whether a field is optional, required, or repeated. */
export enum Field_Cardinality {
    UNKNOWN = 0,
    OPTIONAL = 1,
    REQUIRED = 2,
    REPEATED = 3,
}

/** The syntax in which a protocol buffer element is defined. */
export enum Syntax {
    PROTO2 = 0,
    PROTO3 = 1,
    EDITIONS = 2,
}
